import { useRef, useState } from 'react';
import { TokenSearchField } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';

export type FilterToken = { id: string; label: string; value: string };
export type SearchValue = { text: string; tokens: FilterToken[] };
export type Selection = { start: number; end: number };
export type SearchAction =
  | { type: 'search.change'; value: SearchValue }
  | { type: 'search.submit'; value: SearchValue };
type Suggestion = { id: string; label: string; token: FilterToken };
type EditorHandle = { focus: () => void; setSelectionRange: (start: number, end: number) => void };
export function SearchEditor({ value, dispatch, parse, suggestions }: {
  value: SearchValue;
  dispatch: (action: SearchAction) => void;
  parse: (text: string, tokens: readonly FilterToken[]) => SearchValue;
  suggestions: readonly Suggestion[];
}) {
  const editor = useRef<EditorHandle>(null);
  const caret = useRef<Selection>({ start: 0, end: 0 });
  const [announcement, announce] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  function update(next: SearchValue, selection: Selection = caret.current) {
    dispatch({ type: 'search.change', value: next });
    requestAnimationFrame(() => {
      editor.current?.focus();
      editor.current?.setSelectionRange(selection.start, selection.end);
    });
  }
  function remove(id: string) {
    const token = value.tokens.find(token => token.id === id);
    update({ ...value, tokens: value.tokens.filter(token => token.id !== id) });
    if (editingId === id) setEditingId(null);
    announce(token ? 'Removed filter ' + token.label : '');
  }
  function replace(suggestion: Suggestion) {
    const exists = editingId !== null && value.tokens.some(token => token.id === editingId);
    const tokens = exists
      ? value.tokens.map(token => token.id === editingId ? { ...suggestion.token, id: token.id } : token)
      : [...value.tokens, suggestion.token];
    update({ ...value, tokens });
    setEditingId(null);
    announce((exists ? 'Replaced filter with ' : 'Added filter ') + suggestion.label);
  }
  return <form role="search" className="kui-layout" onSubmit={event => {
    event.preventDefault();
    dispatch({ type: 'search.submit', value: parse(value.text, value.tokens) });
  }}>
    <TokenSearchField ref={editor} aria-label="Search projects and filters"
      value={value.text} tokens={value.tokens}
      onSelectionChange={(selection: Selection) => { caret.current = selection; }}
      onChange={(text: string) => dispatch({ type: 'search.change', value: { ...value, text } })}
      onTokenRemove={remove}
      onTokenEdit={(id: string) => { setEditingId(id); announce('Choose a replacement filter below.'); }}
      onClear={() => {
        setEditingId(null);
        update({ text: '', tokens: [] }, { start: 0, end: 0 });
        announce('Search cleared');
      }} />
    {suggestions.length > 0 && <section aria-label={editingId ? 'Replacement filters' : 'Suggested filters'}>
      {suggestions.map(suggestion => <button key={suggestion.id} type="button"
        onClick={() => replace(suggestion)}>{suggestion.label}</button>)}
    </section>}
    {editingId && <button type="button" onClick={() => { setEditingId(null); editor.current?.focus(); }}>Cancel replacement</button>}
    <button type="submit">Search</button>
    <span role="status" aria-live="polite">{announcement}</span>
  </form>;
}
// TokenSearchField owns the single editor's token traversal/removal keyboard behavior.
// Product parsing, suggestion generation, stable token identity, and search transport stay here.
